import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"Knowledge base","description":"","frontmatter":{},"headers":[],"relativePath":"guide/materials.md","filePath":"guide/materials.md","lastUpdated":1793314357000}'),r={name:"guide/materials.md"};function n(i,e,d,c,h,l){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="knowledge-base" tabindex="-1">Knowledge base <a class="header-anchor" href="#knowledge-base" aria-label="Permalink to &quot;Knowledge base&quot;">​</a></h1><p>This page shows how to give MeetCue background about you and the meeting, so the hints build on your real experience instead of generic answers, and how to see and change the instructions the hint model gets.</p><h2 id="describe-your-role" tabindex="-1">Describe your role <a class="header-anchor" href="#describe-your-role" aria-label="Permalink to &quot;Describe your role&quot;">​</a></h2><p>In <strong>Settings › Hints › My role</strong>, write one sentence about yourself, for example:</p><blockquote><p>Network architect with 8 years in data center operations</p></blockquote><p>The hint model writes talking points from this perspective.</p><h2 id="add-files" tabindex="-1">Add files <a class="header-anchor" href="#add-files" aria-label="Permalink to &quot;Add files&quot;">​</a></h2><ol><li>Open <strong>Settings › Hints</strong>.</li><li>Under <strong>Knowledge base</strong>, click <strong>Add files…</strong>. You can pick several files at once.</li><li>Choose a résumé, project notes, a slide deck, a job description, an agenda or similar.</li></ol><p>Supported formats:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Extensions</th></tr></thead><tbody><tr><td>PDF</td><td><code>.pdf</code></td></tr><tr><td>Word</td><td><code>.docx</code>, <code>.docm</code></td></tr><tr><td>Excel</td><td><code>.xlsx</code>, <code>.xlsm</code> (every sheet, as rows of cells)</td></tr><tr><td>PowerPoint</td><td><code>.pptx</code>, <code>.pptm</code> (slide text and speaker notes)</td></tr><tr><td>OpenDocument</td><td><code>.odt</code>, <code>.ods</code>, <code>.odp</code></td></tr><tr><td>Other documents</td><td><code>.rtf</code>, <code>.html</code>, <code>.htm</code></td></tr><tr><td>Text</td><td><code>.txt</code>, <code>.md</code>, <code>.csv</code>, <code>.tsv</code>, <code>.json</code>, <code>.yaml</code>, <code>.log</code></td></tr></tbody></table><p>MeetCue extracts the text on your computer and shows how many characters were found. Old <code>.doc</code>, <code>.xls</code> and <code>.ppt</code> files can&#39;t be read: open them in Office and save them as <code>.docx</code>, <code>.xlsx</code> or <code>.pptx</code> first. Scanned PDFs without a text layer yield no text; export them with text recognition first. Adding a file again replaces the earlier copy.</p><h2 id="how-the-knowledge-base-is-used" tabindex="-1">How the knowledge base is used <a class="header-anchor" href="#how-the-knowledge-base-is-used" aria-label="Permalink to &quot;How the knowledge base is used&quot;">​</a></h2><ul><li><strong>Short files</strong> (up to about 3,000 characters in total) are sent whole with every question.</li><li><strong>Longer files</strong> are split into passages. For each question, MeetCue picks the passages that share the most words with it, up to about 2,400 characters, and adds them to that question&#39;s request. A short overview of every file is also included. The search runs on your computer, in well under a millisecond, so it doesn&#39;t slow the hints down.</li></ul><p>The hint model is told to build its answer on the experience these notes describe, and to use your real projects, names and figures instead of inventing them.</p><p>To check what a question would get, type it under <strong>Try a question</strong> and click <strong>Show matches</strong>. Nothing is sent anywhere.</p><h2 id="what-is-sent" tabindex="-1">What is sent <a class="header-anchor" href="#what-is-sent" aria-label="Permalink to &quot;What is sent&quot;">​</a></h2><ul><li>The overview, and the passages that match each question, go to the hint model.</li><li>The most distinctive terms (product names, acronyms, people&#39;s names) are sent to the speech recognition provider as hints, so they are recognised correctly.</li><li>The full text stays on your computer. It is never included in diagnostics exports.</li></ul><p>The overview is placed in the part of the instructions that stays the same during a meeting. Providers that support prompt caching then charge much less for it after the first question.</p><p>To try it with a mock interview, use one of the sample job descriptions: <a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/materials/jd-software-engineer.md" target="_blank" rel="noreferrer">jd-software-engineer.md</a> or <a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/materials/jd-security-ai.md" target="_blank" rel="noreferrer">jd-security-ai.md</a>. They match the built-in sample interviews in <a href="/meetcue/guide/mock-interview">Mock interview</a>.</p><h2 id="change-the-prompts" tabindex="-1">Change the prompts <a class="header-anchor" href="#change-the-prompts" aria-label="Permalink to &quot;Change the prompts&quot;">​</a></h2><p><strong>Settings › Hints › Prompts</strong> shows the two prompts the hint model gets, and lets you edit them:</p><ul><li><strong>Instructions</strong> are the same for every question. Placeholders: <code>{role}</code> (your role), <code>{materials}</code> (the knowledge base overview), <code>{output_language}</code>.</li><li><strong>Question message</strong> is sent with each question. Placeholders: <code>{knowledge}</code> (the matching passages), <code>{transcript}</code> (the recent conversation), <code>{question}</code>.</li></ul><p>A placeholder you remove means that information no longer reaches the model; MeetCue warns you when one is missing. Keep the reply format described in the instructions (numbered JSON lines, a line with <code>---</code>, then the sample answer), or the panel can&#39;t show the hints.</p><p>Edited prompts are marked <strong>Edited</strong>. <strong>Restore built-in</strong> goes back to the built-in text, which is updated with new versions of MeetCue. Changes apply to the next question, even during a meeting.</p><h2 id="keep-it-focused" tabindex="-1">Keep it focused <a class="header-anchor" href="#keep-it-focused" aria-label="Permalink to &quot;Keep it focused&quot;">​</a></h2><p>The passages are picked by shared words, so files that use the same terms as the questions work best: write project notes in the language of the meeting, and name the technologies you used. Remove files you no longer need with <strong>Remove</strong>.</p>',26)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
